import React from 'react';
import userEvent from '@testing-library/user-event';
import { render, screen } from '@testing-library/react';
import { Pagination } from '.';

describe('Pagination', () => {
  describe('Desktop screen size', () => {
    test('should render pagination with two items', () => {
      render(<Pagination total={50} pageSize={25} />);

      const firstPage = screen.getByText('1');
      const thirdPage = screen.queryByText('3');

      expect(firstPage).toBeInTheDocument();
      expect(thirdPage).not.toBeInTheDocument();
    });

    test('should be able to change currentPage when prop current is passed', () => {
      const { rerender } = render(<Pagination total={50} pageSize={25} />);

      expect(screen.getByText('1 - 25 of 50')).toBeInTheDocument();
      rerender(<Pagination total={50} pageSize={25} current={2} />);
      expect(screen.getByText('26 - 50 of 50')).toBeInTheDocument();
    });

    test('should render pagination with five or more pages', () => {
      render(<Pagination total={700} pageSize={25} />);

      const firstPage = screen.getByText('1');
      const fifth = screen.getByText('5');

      expect(firstPage).toBeInTheDocument();
      expect(fifth).toBeInTheDocument();
    });

    test('should show two more elements when clicked on one of the two last pages', async () => {
      const user = userEvent.setup();
      render(<Pagination total={700} pageSize={25} />);

      const fifth = screen.getByText('5');
      await user.click(fifth);
      expect(screen.getByText('7')).toBeInTheDocument();
    });

    test('should show two more elements when focus and press enter on one of the two last pages', async () => {
      const user = userEvent.setup();
      render(<Pagination total={700} pageSize={25} />);

      const fifth = screen.getByTitle('page 5');
      fifth.focus();
      await user.keyboard('[Enter]');
      expect(screen.getByText('7')).toBeInTheDocument();
    });

    test('should render only two pages when totalElements/pageSize is equal less than the minimum pages', () => {
      render(<Pagination total={50} pageSize={25} />);

      expect(screen.getByText('2')).toBeInTheDocument();
      expect(screen.queryByText('5')).not.toBeInTheDocument();
    });

    test('should call onChange with the right params when clicked on a page', async () => {
      const user = userEvent.setup();
      const mockOnchange = jest.fn();
      render(<Pagination total={50} pageSize={25} onChange={mockOnchange} />);
      const secondPage = screen.getByText('2');
      await user.click(secondPage);
      expect(mockOnchange).toHaveBeenCalledWith(2, 25);
    });

    test('should render with custom translation strings', () => {
      render(
        <Pagination
          total={50}
          pageSize={25}
          pageSizeOptionsIntl={(option) => `Mostrar ${option} itens por página`}
          quantityIndicatorIntl="de"
        />
      );

      expect(screen.getByText('1 - 25 de 50')).toBeInTheDocument();
      expect(screen.getAllByText(/Mostrar 25 itens por página/i)[0]).toBeVisible();
    });

    describe('Disabled', () => {
      test('should be unable to change pages when disabled', () => {
        render(<Pagination total={700} pageSize={25} disabled />);

        const fifthPage = screen.getByText('5');
        expect(fifthPage).toHaveAttribute('aria-disabled', 'true');
      });

      test('should be unable to click go to last page icon when disabled', () => {
        render(<Pagination total={700} pageSize={25} disabled />);

        expect(screen.getByText('5')).toBeInTheDocument();

        const goToLastPageIcon = screen.getByTitle('last page');
        expect(goToLastPageIcon.firstChild).toHaveAttribute('aria-disabled', 'true');
      });

      test('should be unable to click go to first page icon when disabled', () => {
        render(<Pagination total={700} pageSize={25} current={28} disabled />);

        expect(screen.getByText('28')).toBeInTheDocument();

        const goToFirstPageIcon = screen.getByTitle('first page');
        expect(goToFirstPageIcon.firstChild).toHaveAttribute('aria-disabled', 'true');
      });
    });

    describe('Navigation icons', () => {
      test('should go to the lastPage when the >> icon is clicked', async () => {
        const user = userEvent.setup();
        render(<Pagination total={700} pageSize={25} />);

        expect(screen.getByText('5')).toBeInTheDocument();

        const goToLastPageIcon = screen.getByTitle('last page');
        await user.click(goToLastPageIcon);
        expect(screen.getByText('24', { selector: 'a' })).toBeInTheDocument();
        expect(screen.getByText('25', { selector: 'a' })).toBeInTheDocument();
        expect(screen.getByText('26', { selector: 'a' })).toBeInTheDocument();
        expect(screen.getByText('27', { selector: 'a' })).toBeInTheDocument();
        expect(screen.getByText('28', { selector: 'span' })).toBeInTheDocument();
      });

      test('should go to the lastPage when the >> icon is on focus and pressing enter', async () => {
        const user = userEvent.setup();
        render(<Pagination total={700} pageSize={25} />);

        expect(screen.getByText('5')).toBeInTheDocument();

        const goToLastPageIcon = screen.getByTitle('last page');
        goToLastPageIcon.focus();
        await user.keyboard('[Enter]');
        expect(screen.getByText('24', { selector: 'a' })).toBeInTheDocument();
        expect(screen.getByText('25', { selector: 'a' })).toBeInTheDocument();
        expect(screen.getByText('26', { selector: 'a' })).toBeInTheDocument();
        expect(screen.getByText('27', { selector: 'a' })).toBeInTheDocument();
        expect(screen.getByText('28', { selector: 'span' })).toBeInTheDocument();
      });

      test('should go to the first page when the << icon is clicked', async () => {
        const user = userEvent.setup();
        render(<Pagination total={700} pageSize={25} current={28} />);

        expect(screen.getByText('28')).toBeInTheDocument();

        const goToFirstPageIcon = screen.getByTitle('first page');
        await user.click(goToFirstPageIcon);
        expect(screen.getByText('1')).toBeInTheDocument();
        expect(screen.getByText('2')).toBeInTheDocument();
        expect(screen.getByText('3')).toBeInTheDocument();
        expect(screen.getByText('4')).toBeInTheDocument();
        expect(screen.getByText('5')).toBeInTheDocument();
      });

      test('should go to the first page when the << icon is on focus and pressing enter', async () => {
        const user = userEvent.setup();
        render(<Pagination total={700} pageSize={25} current={28} />);

        expect(screen.getByText('28')).toBeInTheDocument();

        const goToFirstPageIcon = screen.getByTitle('first page');
        goToFirstPageIcon.focus();
        await user.keyboard('[Enter]');
        expect(screen.getByText('1')).toBeInTheDocument();
        expect(screen.getByText('2')).toBeInTheDocument();
        expect(screen.getByText('3')).toBeInTheDocument();
        expect(screen.getByText('4')).toBeInTheDocument();
        expect(screen.getByText('5')).toBeInTheDocument();
      });

      test('should go forward one page when the > icon is clicked', async () => {
        const user = userEvent.setup();
        render(<Pagination total={700} pageSize={25} />);

        const forwardOnePageIcon = screen.getAllByTitle('next page')[1];
        user.click(forwardOnePageIcon);
        expect(screen.getByText('1')).toBeInTheDocument();
        expect(screen.getByText('2')).toBeInTheDocument();
        expect(screen.getByText('3')).toBeInTheDocument();
        expect(screen.getByText('4')).toBeInTheDocument();
        expect(screen.getByText('5')).toBeInTheDocument();
      });

      test('should go forward one page when the > icon is on focus and pressing enter', async () => {
        const user = userEvent.setup();
        render(<Pagination total={700} pageSize={25} />);

        const forwardOnePageIcon = screen.getAllByTitle('next page')[1];
        forwardOnePageIcon.focus();
        user.keyboard('[Enter]');
        expect(screen.getByText('1')).toBeInTheDocument();
        expect(screen.getByText('2')).toBeInTheDocument();
        expect(screen.getByText('3')).toBeInTheDocument();
        expect(screen.getByText('4')).toBeInTheDocument();
        expect(screen.getByText('5')).toBeInTheDocument();
      });

      test('should go backward one page when the < icon is clicked', async () => {
        const user = userEvent.setup();
        render(<Pagination total={700} pageSize={25} current={4} />);

        const backOnePageIcon = screen.getAllByTitle('previous page')[1];
        await user.click(backOnePageIcon);
        expect(screen.getByText('1')).toBeInTheDocument();
        expect(screen.getByText('2')).toBeInTheDocument();
        expect(screen.getByText('3')).toBeInTheDocument();
        expect(screen.getByText('4')).toBeInTheDocument();
        expect(screen.getByText('5')).toBeInTheDocument();
      });

      test('should go backward one page when the < icon is on focus and pressing enter', async () => {
        const user = userEvent.setup();
        render(<Pagination total={700} pageSize={25} current={4} />);

        const backOnePageIcon = screen.getAllByTitle('previous page')[1];
        backOnePageIcon.focus();
        await user.keyboard('[Enter]');
        expect(screen.getByText('1')).toBeInTheDocument();
        expect(screen.getByText('2')).toBeInTheDocument();
        expect(screen.getByText('3')).toBeInTheDocument();
        expect(screen.getByText('4')).toBeInTheDocument();
        expect(screen.getByText('5')).toBeInTheDocument();
      });
    });

    describe('Quantity indicator', () => {
      test('should render by default', () => {
        render(<Pagination total={700} pageSize={25} />);

        const el = screen.getByText('1 - 25 of 700');
        const countOf = screen.getAllByText('of', { exact: false });

        expect(el).toBeInTheDocument();
        expect(countOf).toHaveLength(2);
      });

      test('should not render quantity indicator when prop is false', () => {
        render(<Pagination total={700} pageSize={25} showQuantityIndicator={false} />);

        const countOf = screen.getAllByText('of', { exact: false });

        expect(countOf).toHaveLength(1);
      });

      test('should change the value when another page is clicked', async () => {
        const user = userEvent.setup();
        render(<Pagination total={700} pageSize={25} />);

        const secondPage = screen.getByText('2');
        await user.click(secondPage);
        const quantityIndicator = screen.getByText('26 - 50 of 700');

        expect(quantityIndicator).toBeInTheDocument();
      });
    });

    describe('PageSize selector', () => {
      test('should not render page size selector when showPageSizeSelector is set false', () => {
        render(<Pagination total={700} pageSize={25} showPageSizeSelector={false} />);

        const el = screen.queryByText('Show', { exact: false });

        expect(el).not.toBeInTheDocument();
      });

      test('should be able to change page size', async () => {
        const user = userEvent.setup();
        render(<Pagination total={700} pageSize={25} />);

        const select = screen.getByRole('combobox');

        await user.click(select);

        const option = screen.getByText('Show 10 items per page');

        await user.click(option);

        expect(screen.getByText('1 - 10 of 700')).toBeInTheDocument();
      });

      test('should call onChange prop when page size changed', async () => {
        const user = userEvent.setup();
        const mockOnChange = jest.fn();

        render(<Pagination total={700} pageSize={25} onChange={mockOnChange} />);

        const select = screen.getByRole('combobox');

        await user.click(select);

        const option = screen.getByText('Show 10 items per page');

        await user.click(option);

        expect(screen.getByText('1 - 10 of 700')).toBeInTheDocument();

        expect(mockOnChange).toHaveBeenCalledWith(1, 10);
      });

      test('should render with default page size passed as prop', async () => {
        const user = userEvent.setup();
        render(<Pagination total={700} pageSizeOptions={[25, 60, 100]} defaultPageSize={60} />);

        const firstOptionElement = screen.getByText('Show 60 items per page');

        expect(firstOptionElement).toBeInTheDocument();

        const select = screen.getByRole('combobox');

        await user.click(select);

        const option = screen.getByText('Show 100 items per page');

        await user.click(option);

        expect(screen.getByText('1 - 100 of 700')).toBeInTheDocument();
      });

      test('should render custom list of options', async () => {
        const user = userEvent.setup();
        render(<Pagination total={700} pageSizeOptions={[25, 60, 100]} />);

        const firstOptionElement = screen.getByText('Show 25 items per page');

        expect(firstOptionElement).toBeInTheDocument();

        const select = screen.getByRole('combobox');

        await user.click(select);

        const option = screen.getByText('Show 60 items per page');

        await user.click(option);

        expect(screen.getByText('1 - 60 of 700')).toBeInTheDocument();
      });

      test('should go to the actual last page when changing to a lower page size and was already on the last page', async () => {
        const user = userEvent.setup();
        render(
          <Pagination
            total={700}
            pageSizeOptions={[25, 60, 100]}
            current={28}
            defaultPageSize={25}
          />
        );

        const select = screen.getByRole('combobox');

        await user.click(select);

        const option = screen.getByText('Show 100 items per page');

        await user.click(option);

        expect(screen.getByText('7')).toBeInTheDocument();
        expect(screen.getByText('6')).toBeInTheDocument();
        expect(screen.getByText('5')).toBeInTheDocument();
        expect(screen.getByText('4')).toBeInTheDocument();
        expect(screen.getByText('3')).toBeInTheDocument();
      });
    });
  });

  describe('Mobile screen size', () => {
    beforeAll(() => {
      global.innerWidth = 480;
      global.dispatchEvent(new Event('resize'));
    });

    test('should render the mobile version when screen size is less than breakpoint', () => {
      render(<Pagination total={700} pageSize={25} />);

      expect(screen.getByText('1 of 28')).toBeInTheDocument();
    });

    test('should be able to change page clicking on the navigation icons', async () => {
      const user = userEvent.setup();
      render(<Pagination total={700} pageSize={25} />);

      const navIconRight = screen.getAllByTitle('next page')[0];

      await user.click(navIconRight);

      expect(screen.getByText('2 of 28')).toBeInTheDocument();
    });

    test('should be able to change page when focus on the navigation icons and pressing enter', async () => {
      const user = userEvent.setup();
      render(<Pagination total={700} pageSize={25} />);

      const navIconRight = screen.getAllByTitle('next page')[0];

      navIconRight.focus();
      await user.keyboard('[Enter]');

      expect(screen.getByText('2 of 28')).toBeInTheDocument();
    });

    test('should be able go back one page', async () => {
      const user = userEvent.setup();
      render(<Pagination total={700} pageSize={25} current={4} />);

      expect(screen.getByText('4 of 28')).toBeInTheDocument();

      const navIconLeft = screen.getAllByTitle('previous page')[0];

      await user.click(navIconLeft);

      expect(screen.getByText('3 of 28')).toBeInTheDocument();
    });

    test('should be able go back one page when focus and pressing enter', async () => {
      const user = userEvent.setup();
      render(<Pagination total={700} pageSize={25} current={4} />);

      expect(screen.getByText('4 of 28')).toBeInTheDocument();

      const navIconLeft = screen.getAllByTitle('previous page')[0];

      navIconLeft.focus();
      await user.keyboard('[Enter]');

      expect(screen.getByText('3 of 28')).toBeInTheDocument();
    });

    test('should be able to change the page number inside the page indicator input', async () => {
      const user = userEvent.setup();
      render(<Pagination total={700} pageSize={25} />);

      await user.click(screen.getByText('1 of 28'));

      const pageNavInput = screen.getByDisplayValue('1');

      await user.clear(pageNavInput);

      await user.type(pageNavInput, '3');

      pageNavInput.blur();

      expect(screen.getByText('3 of 28')).toBeInTheDocument();
    });

    test('should change to last page when the input is given a number bigger than the number of total pages', async () => {
      const user = userEvent.setup();
      render(<Pagination total={700} pageSize={25} />);

      await user.click(screen.getByText('1 of 28'));

      const pageNavInput = screen.getByDisplayValue('1');

      await user.clear(pageNavInput);
      await user.type(pageNavInput, '45');

      pageNavInput.blur();

      expect(screen.getByText('28 of 28')).toBeInTheDocument();
    });

    test('should be able to change page when the input is visible', async () => {
      const user = userEvent.setup();
      render(<Pagination total={700} pageSize={25} />);

      await user.click(screen.getByText('1 of 28'));
      await user.click(screen.getAllByTitle('next page')[0]);

      expect(screen.getByText('2 of 28')).toBeInTheDocument();
    });

    test('should accept only numbers as input value for page navigation', async () => {
      const user = userEvent.setup();
      render(<Pagination total={700} pageSize={25} />);

      await user.click(screen.getByText('1 of 28'));

      const pageNavInput = screen.getByDisplayValue('1');
      await user.clear(pageNavInput);
      await user.type(pageNavInput, 'abcd');
      pageNavInput.blur();

      expect(screen.getByText('1 of 28')).toBeInTheDocument();
    });

    test('should not be able to change page when disabled', async () => {
      const user = userEvent.setup();
      render(<Pagination total={700} pageSize={25} disabled />);

      await user.click(screen.getByText('1 of 28'));

      const pageNavInput = screen.queryByDisplayValue('1');

      expect(pageNavInput).not.toBeInTheDocument();
    });

    test('should not be able to change page when disabled using nav icons', () => {
      render(<Pagination total={700} pageSize={25} disabled />);

      const forwardIcon = screen.getAllByTitle('next page')[0];
      const backwardIcon = screen.getAllByTitle('previous page')[0];

      expect(backwardIcon.firstChild).toHaveAttribute('aria-disabled', 'true');
      expect(forwardIcon.firstChild).toHaveAttribute('aria-disabled', 'true');
    });

    test('should not be showed the pagination when the total items is 0', async () => {
      render(<Pagination total={0} pageSize={25} disabled />);
      expect(screen.queryByTestId('pagination-container')).not.toBeTruthy();
    });
  });
});
